export const DeliveryDashboard: React.FC = () => {
    const { orders, currentUser, assignDelivery, updateOrderStatus, refreshData, couriers, toggleDriverStatus, updateDriverLocation } = useApp();
    const [activeTab, setActiveTab] = useState<'available' | 'active' | 'history'>('available');
    const [isRefreshing, setIsRefreshing] = useState(false);
    const [acceptingId, setAcceptingId] = useState<string | null>(null);
    const [currentLocation, setCurrentLocation] = useState<{lat: number, lng: number} | null>(null);

    // Simulating GPS Movement
    const simulationInterval = useRef<any>(null);

    // Get current rider profile
    const me = couriers.find(d => d.userId === currentUser?.id);
    const isOnline = me?.onlineStatus || false;

    // --- GPS Logic ---
    useEffect(() => {
        if (!isOnline) {
            if (simulationInterval.current) clearInterval(simulationInterval.current);
            return;
        }

        // 1. Get Initial Position
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (pos) => {
                    const { latitude, longitude } = pos.coords;
                    setCurrentLocation({ lat: latitude, lng: longitude });
                    updateDriverLocation(latitude, longitude);
                },
                (err) => console.error("GPS Error", err),
                { enableHighAccuracy: true }
            );
        }

        // 2. Simulate Movement / Update Loop
        simulationInterval.current = setInterval(() => {
             setCurrentLocation(prev => {
                 if(!prev) return { lat: 5.6506, lng: -0.1962 }; // Default

                 // Simulate small jitter to show "live" effect
                 const newLat = prev.lat + (Math.random() - 0.5) * 0.0001;
                 const newLng = prev.lng + (Math.random() - 0.5) * 0.0001;

                 updateDriverLocation(newLat, newLng);
                 return { lat: newLat, lng: newLng };
             });
        }, 5000); // Update every 5s

        return () => clearInterval(simulationInterval.current);
    }, [isOnline]);


    // --- Map Logic for Active Job ---
    const mapRef = useRef<HTMLDivElement>(null);
    const mapInstance = useRef<any>(null);

    const activeJob = orders.find(o => 
        o.courierId === currentUser?.id && 
        o.status !== 'delivered' && o.status !== 'cancelled'
    );

    useEffect(() => {
        if (activeTab === 'active' && activeJob && mapRef.current && window.L) {
             if (!mapInstance.current) {
                 mapInstance.current = window.L.map(mapRef.current).setView([5.6506, -0.1962], 14);
                 window.L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
                    attribution: '&copy; OpenStreetMap',
                 }).addTo(mapInstance.current);
             }

             const map = mapInstance.current;
             // Clear existing layers (simple way)
             map.eachLayer((layer: any) => {
                 if (!layer._url) map.removeLayer(layer);
             });

             // 1. Driver Marker
             if (currentLocation) {
                 window.L.marker([currentLocation.lat, currentLocation.lng], {
                     icon: window.L.divIcon({
                         className: 'bg-transparent',
                         html: '<div class="w-4 h-4 bg-blue-600 rounded-full border-2 border-white shadow-lg pulse-ring"></div>'
                     })
                 }).addTo(map);
             }

             // 2. Pickup (Vendor)
             if (activeJob.pickupCoordinates) {
                 window.L.marker([activeJob.pickupCoordinates.lat, activeJob.pickupCoordinates.lng], {
                     icon: window.L.divIcon({ html: '<i class="fa-solid fa-store text-purple-600 text-2xl drop-shadow-md"></i>', className: 'bg-transparent' })
                 }).addTo(map);
             }

             // 3. Dropoff (Buyer)
             if (activeJob.locationCoordinates) {
                 window.L.marker([activeJob.locationCoordinates.lat, activeJob.locationCoordinates.lng], {
                     icon: window.L.divIcon({ html: '<i class="fa-solid fa-location-dot text-red-600 text-2xl drop-shadow-md"></i>', className: 'bg-transparent' })
                 }).addTo(map);
             }

             // Fit bounds
             const bounds = [];
             if (currentLocation) bounds.push([currentLocation.lat, currentLocation.lng]);
             if (activeJob.pickupCoordinates) bounds.push([activeJob.pickupCoordinates.lat, activeJob.pickupCoordinates.lng]);
             if (activeJob.locationCoordinates) bounds.push([activeJob.locationCoordinates.lat, activeJob.locationCoordinates.lng]);

             if(bounds.length > 0) map.fitBounds(bounds, { padding: [50, 50] });
        }
    }, [activeTab, activeJob, currentLocation]);


    const handleRefresh = async () => {
        setIsRefreshing(true);
        await refreshData();
        setIsRefreshing(false);
    };

    const handleAccept = async (orderId: string) => {
        setAcceptingId(orderId);
        await assignDelivery(orderId);
        setActiveTab('active');
        setAcceptingId(null);
    };

    // Haversine Distance Helper
    const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number) => {
        const R = 6371; // km
        const dLat = (lat2 - lat1) * Math.PI / 180;
        const dLon = (lon2 - lon1) * Math.PI / 180;
        const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
                Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
                Math.sin(dLon/2) * Math.sin(dLon/2);
        const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
        return R * c;
    };

    // Status Checks
    if (!me || me.status === 'pending') return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50 p-6 text-center">
            <div>
                <i className="fa-solid fa-clock text-4xl text-yellow-500 mb-4"></i>
                <h2 className="text-xl font-bold text-gray-900">Account Pending</h2>
                <p className="text-gray-500 mt-2">Your courier application is under review by admin.</p>
                <Button variant="ghost" className="mt-4" onClick={handleRefresh}>Check Status</Button>
            </div>
        </div>
    );

    if (me.status === 'suspended') return <div className="min-h-screen flex items-center justify-center p-6 text-center text-red-500">Account Suspended</div>;

    // Filter Logic
    const availableJobs = orders.filter(o => {
        const isReady = o.status === 'ready_for_pickup' && o.deliveryOption === 'delivery' && !o.courierId;
        if (!isReady) return false;

        // Smart Matching: Only show jobs within 5km if we have location
        if (currentLocation && o.pickupCoordinates) {
            const dist = calculateDistance(currentLocation.lat, currentLocation.lng, o.pickupCoordinates.lat, o.pickupCoordinates.lng);
            return dist <= 5; 
        }
        return true; // Fallback if no GPS
    });

    const myHistory = orders.filter(o => o.courierId === currentUser?.id && o.status === 'delivered');
    const totalEarnings = myHistory.length * 10; 

    const getNextStep = (status: string) => {
        if (status === 'courier_assigned') return { label: 'Confirm Pickup', next: 'picked_up', icon: 'box-open' };
        if (status === 'picked_up') return { label: 'Start Route', next: 'delivering', icon: 'route' };
        if (status === 'delivering') return { label: 'Mark Delivered', next: 'delivered', icon: 'flag-checkered' };
        return null;
    };

    return (
        <div className="min-h-screen bg-gray-50 pb-24 animate-fade-in pb-safe">
            {/* Header */}
            <div className={`p-6 text-white rounded-b-3xl shadow-lg mb-6 sticky top-0 z-10 transition-colors duration-500 ${isOnline ? 'bg-blue-600' : 'bg-gray-800'}`}>
                <div className="flex justify-between items-center mb-4">
                    <h1 className="text-2xl font-display font-bold">Courier Hub</h1>
                    <div className="flex items-center gap-3">
                        <Button 
                            size="sm" 
                            variant="ghost" 
                            className="text-white hover:bg-white/20 bg-white/10" 
                            onClick={handleRefresh}
                        >
                            <i className={`fa-solid fa-rotate ${isRefreshing ? 'animate-spin' : ''}`}></i>
                        </Button>
                        <div 
                            className={`flex items-center gap-2 px-3 py-1 rounded-full cursor-pointer transition-all border ${isOnline ? 'bg-green-500 border-green-400' : 'bg-gray-700 border-gray-600'}`}
                            onClick={() => toggleDriverStatus(!isOnline)}
                        >
                            <span className={`w-2 h-2 rounded-full ${isOnline ? 'bg-white animate-pulse' : 'bg-gray-400'}`}></span>
                            <span className="text-xs font-bold uppercase tracking-wider">{isOnline ? 'Online' : 'Offline'}</span>
                        </div>
                    </div>
                </div>
                {isOnline ? (
                    <div className="grid grid-cols-2 gap-4 animate-fade-in">
                        <div className="bg-blue-500/30 p-3 rounded-xl backdrop-blur-sm">
                            <p className="text-blue-100 text-[10px] font-bold uppercase">Earnings</p>
                            <p className="text-2xl font-bold">₵{totalEarnings.toFixed(2)}</p>
                        </div>
                        <div className="bg-blue-500/30 p-3 rounded-xl backdrop-blur-sm">
                            <p className="text-blue-100 text-[10px] font-bold uppercase">Completed</p>
                            <p className="text-2xl font-bold">{myHistory.length}</p>
                        </div>
                    </div>
                ) : (
                    <div className="text-center py-2 text-gray-400 text-sm">You are offline. Go online to receive orders.</div>
                )}
            </div>

            <div className="px-4">
                {/* Tabs */}
                <div className="flex bg-white p-1 rounded-xl shadow-sm mb-6 border border-gray-100 sticky top-40 z-10">
                    <button onClick={() => setActiveTab('available')} className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all ${activeTab === 'available' ? 'bg-blue-50 text-blue-600' : 'text-gray-400'}`}>New ({availableJobs.length})</button>
                    <button onClick={() => setActiveTab('active')} className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all ${activeTab === 'active' ? 'bg-blue-50 text-blue-600' : 'text-gray-400'}`}>Current ({activeJob ? 1 : 0})</button>
                    <button onClick={() => setActiveTab('history')} className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all ${activeTab === 'history' ? 'bg-blue-50 text-blue-600' : 'text-gray-400'}`}>History</button>
                </div>

                <div className="space-y-4">
                    {/* AVAILABLE */}
                    {activeTab === 'available' && (
                        !isOnline ? (
                            <div className="text-center py-20 text-gray-400">
                                <i className="fa-solid fa-power-off text-4xl mb-4 opacity-20"></i>
                                <p>You are currently offline.</p>
                            </div>
                        ) : availableJobs.length === 0 ? (
                            <div className="text-center py-20 text-gray-400 animate-pulse">
                                <i className="fa-solid fa-radar text-4xl mb-4 opacity-20"></i>
                                <p>Scanning for nearby orders...</p>
                            </div>
                        ) : (
                            availableJobs.map(job => (
                                <Card key={job.id} className="p-0 overflow-hidden border-l-4 border-l-green-500 animate-slide-up">
                                    <div className="p-4 bg-white">
                                        <div className="flex justify-between items-start mb-2">
                                            <Badge color="green">Ready for Pickup</Badge>
                                            <span className="font-bold text-lg text-green-600">₵10.00</span>
                                        </div>
                                        <div className="flex items-start gap-3 mt-3">
                                            <div className="flex flex-col items-center gap-1 mt-1">
                                                <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                                                <div className="w-0.5 h-8 bg-gray-200"></div>
                                                <div className="w-2 h-2 rounded-full bg-red-500"></div>
                                            </div>
                                            <div className="flex-1 space-y-4">
                                                <div>
                                                    <p className="text-xs text-gray-400 uppercase font-bold">Pickup</p>
                                                    <p className="text-sm font-bold text-gray-800">Vendor #{job.vendorId.slice(-4)}</p>
                                                    {currentLocation && job.pickupCoordinates && <p className="text-xs text-blue-500">{calculateDistance(currentLocation.lat, currentLocation.lng, job.pickupCoordinates.lat, job.pickupCoordinates.lng).toFixed(1)} km away</p>}
                                                </div>
                                                <div>
                                                    <p className="text-xs text-gray-400 uppercase font-bold">Dropoff</p>
                                                    <p className="text-sm font-bold text-gray-800">Customer Location</p>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="bg-gray-50 p-3 border-t border-gray-100">
                                        <Button 
                                            fullWidth 
                                            onClick={() => handleAccept(job.id)}
                                            disabled={acceptingId === job.id}
                                            className="shadow-lg shadow-green-500/20"
                                        >
                                            {acceptingId === job.id ? 'Accepting...' : 'Accept Job'}
                                        </Button>
                                    </div>
                                </Card>
                            ))
                        )
                    )}

                    {/* ACTIVE */}
                    {activeTab === 'active' && (
                        !activeJob ? (
                            <div className="text-center py-10 text-gray-400">
                                <p>No active delivery.</p>
                            </div>
                        ) : (
                            <Card className="p-0 overflow-hidden border-2 border-blue-500 shadow-xl">
                                <div className="bg-blue-600 p-3 text-white flex justify-between items-center">
                                    <span className="font-bold">Current Delivery</span>
                                    <Badge className="bg-white/20 text-white border-transparent">{activeJob.status.replace('_', ' ')}</Badge>
                                </div>

                                {/* Map Container */}
                                <div ref={mapRef} className="h-64 w-full bg-gray-200 z-0"></div>

                                <div className="p-4 bg-white relative z-10 -mt-4 rounded-t-2xl shadow-up">
                                    <div className="flex items-center justify-between mb-4">
                                        <div className="text-center flex-1">
                                            <p className="text-xs text-gray-400 uppercase">Est. Arrival</p>
                                            <p className="font-bold text-xl">10 min</p>
                                        </div>
                                        <div className="w-px h-8 bg-gray-100"></div>
                                        <div className="text-center flex-1">
                                            <p className="text-xs text-gray-400 uppercase">Distance</p>
                                            <p className="font-bold text-xl">2.4 km</p>
                                        </div>
                                    </div>

                                    {(() => {
                                        const step = getNextStep(activeJob.status);
                                        return step ? (
                                            <Button 
                                                fullWidth 
                                                size="lg" 
                                                onClick={() => updateOrderStatus(activeJob.id, step.next as any)} 
                                                className="shadow-lg shadow-blue-500/30 h-14 text-lg"
                                                icon={step.icon}
                                            >
                                                {step.label}
                                            </Button>
                                        ) : null;
                                    })()}
                                </div>
                            </Card>
                        )
                    )}

                    {/* HISTORY */}
                    {activeTab === 'history' && (
                        myHistory.map(job => (
                            <Card key={job.id} className="p-4 opacity-75 hover:opacity-100 transition-opacity">
                                <div className="flex justify-between items-start mb-2">
                                    <span className="font-bold text-gray-900">Order #{job.id.slice(-4)}</span>
                                    <Badge color="green">Delivered</Badge>
                                </div>
                                <div className="flex justify-between items-center pt-3 border-t border-gray-100 mt-2">
                                    <span className="text-xs text-gray-400">{new Date(job.createdAt).toLocaleDateString()}</span>
                                    <span className="font-bold text-green-600 text-lg">+ ₵10.00</span>
                                </div>
                            </Card>
                        ))
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
